import Foundation

/// In-app localization with a runtime language switch (Russian, Uzbek Latin, Uzbek Cyrillic,
/// English). Tables live in L10nTables.swift, generated by tools/gen_l10n.py — edit
/// tools/strings.json, not the generated file.
enum L10n {
    static func table(_ language: AppLanguage) -> [String: String] {
        switch language {
        case .ru: return L10nTables.ru
        case .uz: return L10nTables.uz
        case .uzCyrl: return L10nTables.uzCyrl
        case .en: return L10nTables.en
        }
    }

    static func t(_ key: String, _ language: AppLanguage) -> String {
        table(language)[key] ?? L10nTables.en[key] ?? key
    }

    /// Replaces %1$@, %2$@ … (or a single %@) with the given strings. Only string arguments
    /// are used, so numbers are always formatted for the selected language first.
    static func format(_ key: String, _ language: AppLanguage, _ args: [String]) -> String {
        var result = t(key, language)
        for (index, arg) in args.enumerated() {
            result = result.replacingOccurrences(of: "%\(index + 1)$@", with: arg)
        }
        if let first = args.first {
            result = result.replacingOccurrences(of: "%@", with: first)
        }
        return result
    }

    /// Plural entries are stored as "one|few|many" (Russian) or "one|other" (Uzbek, English).
    static func plural(_ key: String, _ count: Int, _ language: AppLanguage) -> String {
        let forms = t(key, language).components(separatedBy: "|")
        let formatted = Self.number(count, language)
        let index: Int
        switch language {
        case .ru:
            let mod10 = count % 10, mod100 = count % 100
            if mod10 == 1 && mod100 != 11 { index = 0 }
            else if (2...4).contains(mod10) && !(12...14).contains(mod100) { index = 1 }
            else { index = 2 }
        case .en:
            index = count == 1 ? 0 : 1
        case .uz, .uzCyrl:
            index = 0
        }
        let form = forms[min(index, forms.count - 1)]
        return form.replacingOccurrences(of: "%@", with: formatted)
    }

    static func number(_ value: Int, _ language: AppLanguage) -> String {
        value.formatted(.number.locale(language.locale))
    }

    static func duration(_ seconds: Int) -> String {
        let h = seconds / 3600, m = (seconds % 3600) / 60, s = seconds % 60
        return h > 0 ? String(format: "%d:%02d:%02d", h, m, s) : String(format: "%02d:%02d", m, s)
    }

    static func weekdaySymbols(_ language: AppLanguage) -> [String] {
        var calendar = Calendar(identifier: .gregorian)
        calendar.locale = language.locale
        return calendar.shortStandaloneWeekdaySymbols
    }

    /// Weekday numbers (1 = Sunday) ordered from the locale's first weekday.
    static func orderedWeekdays(_ language: AppLanguage) -> [Int] {
        let first = language == .en ? 1 : 2
        return (0..<7).map { ((first - 1 + $0) % 7) + 1 }
    }

    static func shortDate(_ key: String, _ language: AppLanguage) -> String {
        guard let date = DayKey.date(key) else { return key }
        return date.formatted(.dateTime.day().month(.abbreviated).locale(language.locale))
    }
}
